function bindArchitecture(){const main=document.querySelector('.slide.active .archx-main');if(!main||main.dataset.archBound==='1')return;main.dataset.archBound='1';const dock=main.querySelector('.archx-detail');const data=archDetailData();const clearSel=()=>main.querySelectorAll('.archx-click').forEach(x=>x.classList.remove('selected'));const closeDock=()=>{if(!dock)return;dock.classList.remove('open');clearSel();};const placeDock=(ev)=>{if(!dock)return;if(window.innerWidth<=900){dock.style.left='14px';dock.style.right='14px';dock.style.top='auto';dock.style.bottom='14px';return;}dock.style.right='auto';dock.style.bottom='auto';dock.style.left='16px';dock.style.top='16px';const mainRect=main.getBoundingClientRect();const dockRect=dock.getBoundingClientRect();let left=(ev?.clientX||mainRect.left+24)-mainRect.left+18;let top=(ev?.clientY||mainRect.top+24)-mainRect.top-8;const maxLeft=main.clientWidth-dockRect.width-12;const maxTop=main.clientHeight-dockRect.height-12;left=Math.max(12,Math.min(left,maxLeft));top=Math.max(12,Math.min(top,maxTop));dock.style.left=`${left}px`;dock.style.top=`${top}px`;};main.querySelectorAll('.archx-click[data-arch]').forEach(el=>{el.setAttribute('role','button');el.setAttribute('tabindex','0');el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}});el.addEventListener('click',(ev)=>{ev.stopPropagation();clearSel();el.classList.add('selected');const d=data[el.dataset.arch];if(!d||!dock)return;dock.querySelector('.archx-detail-icon').innerHTML=icon(d.icon);dock.querySelector('h4').textContent=d.title;dock.querySelector('p').textContent=d.desc;dock.querySelector('.archx-detail-points').innerHTML=d.points.map(x=>`<span>${esc(x)}</span>`).join('');dock.classList.add('open');placeDock(ev);});});const close=dock?.querySelector('.archx-detail-close');if(close)close.onclick=(ev)=>{ev.stopPropagation();closeDock();};main.addEventListener('click',(ev)=>{if(ev.target.closest('.archx-detail')||ev.target.closest('.archx-click[data-arch]'))return;closeDock();});window.addEventListener('resize',()=>{if(dock?.classList.contains('open'))placeDock();},{passive:true});}
