function flowSlide(t){
  const items=t.flow; const en=state.lang==='en';
  const types=en
    ? ['SOURCE LAYER','TRANSPORT LAYER','AGGREGATION','PRIVATE BACKBONE','SERVICE STACK','ACCESS LAYER','ENDPOINT LAYER']
    : ['طبقة المصدر','طبقة النقل','التجميع','العمود الخاص','طبقة الخدمات','طبقة الوصول','طبقة الأطراف'];
  const chips=[
    en?['Approved sites','Command centers']:['مواقع معتمدة','مراكز قيادة'],
    en?['Private transport','Resilient backbone']:['نقل خاص','عمود فقري مرن'],
    en?['Edge routing','Structured handoff']:['توجيه طرفي','ربط منظم'],
    en?['Policy enforcement','Visibility']:['فرض السياسات','الرؤية'],
    en?['4G/5G core','Security controls']:['نواة 4G/5G','ضوابط أمنية'],
    en?['Mobility','Wireless access']:['تنقل','وصول لاسلكي'],
    en?['Users','IoT + CCTV']:['مستخدمون','إنترنت الأشياء + CCTV']
  ];
  const legend=en
    ? [['Source & service domains','#f17465'],['Animated service path','#d3a24f'],['Private 5G delivery chain','#58b9ff']]
    : [['مجالات المصدر والخدمة','#f17465'],['مسار خدمة متحرك','#d3a24f'],['سلسلة تقديم 5G الخاصة','#58b9ff']];
  const stage=(it,i)=>`<div class="nfStage photo-flow stage${i+1} s${i+1}" style="--flowimg:${cssAsset(cardImageFor(it[2],i))}"><div class="stageNo">${String(i+1).padStart(2,'0')}</div><div class="stageType"><em>${String(i+1).padStart(2,'0')}</em>${types[i]}</div><div class="nfHdr"><div class="nfIcon">${icon(it[2])}</div><div class="nfText"><div class="nfTitle">${esc(it[0])}</div><div class="nfDesc">${esc(it[1])}</div></div></div><div class="nfTags">${chips[i].map(c=>`<span class="nfTag">${esc(c)}</span>`).join('')}</div></div>`;
  return `<div class="frame"><div class="body">${hdr(en?'Structured Service Journey':'رحلة خدمة منظمة', en?'Network Flow':'تدفق الشبكة', en?'A true end-to-end service journey showing how private connectivity moves from approved source sites through transport, core, security and private 5G access to end users and connected assets.':'رحلة خدمة متكاملة توضّح انتقال الاتصال الخاص من المواقع المعتمدة عبر النقل والنواة والأمن ووصول 5G الخاص حتى المستخدمين والأصول المتصلة.',6)}
    <div class="verticalFlow">
      <div class="nfIntro"><div class="nfIntroText">${en?'End-to-end delivery logic: approved sites enter the private transport chain, aggregate into Pulse, pass through core and security services, then exit as private 5G access for users, IoT and CCTV.':'منطق التسليم الشامل: تبدأ المواقع المعتمدة عبر سلسلة النقل الخاصة، ثم تتجمع داخل Pulse، وتمر عبر خدمات النواة والأمن، ثم تخرج كخدمة وصول 5G خاصة للمستخدمين وإنترنت الأشياء وكاميرات المراقبة.'}</div><div class="nfLegend">${legend.map(l=>`<span class="nfLegendItem"><span class="nfLegendSwatch" style="background:${l[1]}"></span>${esc(l[0])}</span>`).join('')}</div></div>
      <div class="nfCanvas">
        <svg class="nfSvg" viewBox="0 0 1000 560" preserveAspectRatio="none" aria-hidden="true">
          <!-- Connections are intentionally restricted to the whitespace between cards. -->
          <path class="nfTraceSegment warm" d="M320 101 L358 101"/>
          <path class="nfTraceSegment warm" d="M646 101 L684 101"/>
          <path class="nfTraceSegment cool" d="M828 168 L828 210"/>
          <path class="nfTraceSegment cool" d="M684 277 L646 277"/>
          <path class="nfTraceSegment" d="M358 277 L320 277"/>
          <path class="nfTraceSegment" d="M250 344 L250 386"/>
        </svg>
        ${items.map((it,i)=>stage(it,i)).join('')}
      </div>
    </div></div></div>`}
function lineElt(x1,y1,x2,y2,dur){const dx=x2-x1,dy=y2-y1,len=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)*180/Math.PI; return `<div class="mline" style="left:${x1}%;top:${y1}%;width:${len}%;transform:rotate(${ang}deg);animation-duration:${dur}s"></div>`}
