function opsTopTicker(){const en=state.lang==='en';const items=en?['Alarms: 14 open • 3 critical • 11 minor','Sites live: 18 / 20 • Crew dispatches: 4','Core load: 63% • VoNR ASR: 99.1% • Latency P95: 8.4 ms','Backhaul fibre health: Normal • DWDM lambdas in service: 24']:['الإنذارات: 14 مفتوحة • 3 حرجة • 11 بسيطة','المواقع النشطة: 18 من 20 • مهام الفرق: 4','حمل النواة: 63% • نسبة إكمال VoNR: 99.1% • كمون P95: 8.4 ms','سلامة الألياف: طبيعي • قنوات DWDM العاملة: 24'];return `<div class="opsTicker"><div class="opsTickerTrack">${items.concat(items).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>`}
function getDrillRows(kind){const en=state.lang==='en';const sets={kpi:[[en?'Availability':'التوافر','99.98%',en?'Rolling 24h':'آخر 24 ساعة'],[en?'Current shift incidents':'حوادث الوردية الحالية','14',en?'3 critical • 11 minor':'3 حرجة • 11 بسيطة'],[en?'Service tickets breached':'تذاكر متجاوزة','2',en?'Target < 5':'المستهدف أقل من 5'],[en?'Escalated to field':'تم التصعيد للميدان','4',en?'West / Central clusters':'العناقيد الغربية / الوسطى']],alarm:[[en?'ALM-2401':'ALM-2401',en?'West Tower 07 power fluctuation':'تذبذب طاقة برج غرب 07',en?'Critical':'حرج'],[en?'ALM-2402':'ALM-2402',en?'Core UPF session spike':'ارتفاع جلسات UPF',en?'Major':'كبير'],[en?'ALM-2403':'ALM-2403',en?'Corniche edge link optical degradation':'تدهور بصري في وصلة الكورنيش',en?'Major':'كبير'],[en?'ALM-2404':'ALM-2404',en?'Sector imbalance • Airport district':'اختلال قطاعي • منطقة المطار',en?'Minor':'بسيط']],site:[[en?'Site':'الموقع',en?'Status':'الحالة',en?'Utilization':'الاستخدام'],['AD-01 Marina',en?'Healthy':'سليم','61%'],['AD-04 Corniche',en?'Attention':'يحتاج انتباه','74%'],['AD-07 Yas',en?'Healthy':'سليم','58%'],['AD-11 Saadiyat',en?'Planned optimization':'تحسين مخطط','49%']],trend:[[en?'Hour':'الساعة',en?'Voice Erlang':'الصوت Erlang',en?'Data Gbit/s':'البيانات جيجابت/ث'],['08:00','32','6.8'],['12:00','48','10.7'],['16:00','57','13.4'],['20:00','42','9.6']]};return sets[kind]||sets.site}
function renderDrillTable(rows){const [head,...body]=rows;return `<div class="drillTable"><div class="drillRow head">${head.map(h=>`<span>${esc(h)}</span>`).join('')}</div>${body.map(r=>`<div class="drillRow">${r.map(c=>`<span>${esc(c)}</span>`).join('')}</div>`).join('')}</div>`}
function openOpsDrilldown(kind,title){const host=document.querySelector('#opsPortal.open .opsDrilldown'); if(!host) return; const en=state.lang==='en'; const notes={kpi:en?'Executive KPI drill-down with thresholds, shift notes and escalations.':'تفاصيل مؤشرات الأداء مع الحدود وملاحظات الوردية والتصعيدات.',alarm:en?'Alarm and ticket queue drill-down with current incident posture.':'تفاصيل قائمة الإنذارات والتذاكر وحالة الحوادث الحالية.',site:en?'Per-site drill-down including utilization, quality and optimization actions.':'تفاصيل كل موقع بما في ذلك الاستخدام والجودة وإجراءات التحسين.',trend:en?'Hourly service trend drill-down for voice and data traffic.':'تفاصيل الاتجاهات الزمنية لخدمات الصوت والبيانات.'}; host.innerHTML=`<div class="opsDrillPanel"><button class="opsDrillClose" aria-label="Close">×</button><div class="opsDrillHeader"><div class="eyebrow">${en?'Drill-down view':'عرض تفصيلي'}</div><h4>${esc(title)}</h4><p>${esc(notes[kind]||notes.site)}</p></div><div class="opsDrillStats"><div><strong>12</strong><span>${en?'Open work items':'عناصر عمل مفتوحة'}</span></div><div><strong>04</strong><span>${en?'Immediate actions':'إجراءات فورية'}</span></div><div><strong>97%</strong><span>${en?'SLA adherence':'الالتزام بمستوى الخدمة'}</span></div></div>${renderDrillTable(getDrillRows(kind))}<div class="opsDrillFooter">${en?'Dummy data for presentation purposes only.':'بيانات تجريبية لأغراض العرض فقط.'}</div></div>`; host.classList.add('open'); const c=host.querySelector('.opsDrillClose'); if(c)c.onclick=()=>closeOpsDrilldown();}
function closeOpsDrilldown(){const host=document.querySelector('#opsPortal.open .opsDrilldown'); if(!host) return; host.classList.remove('open'); host.innerHTML='';}
function bindOpsDrilldowns(){const root=document.querySelector('#opsPortal.open'); if(!root) return; root.querySelectorAll('.dashKpi').forEach((el,i)=>{el.style.cursor='pointer';el.onclick=()=>openOpsDrilldown('kpi',el.querySelector('.dashKpiLabel')?.textContent||`KPI ${i+1}`)}); root.querySelectorAll('.dashcard').forEach((el,i)=>{el.style.cursor='pointer';el.onclick=(ev)=>{if(ev.target.closest('button'))return; const title=el.querySelector('.dashTitle')?.textContent||`Panel ${i+1}`; const kind=i%3===0?'alarm':i%3===1?'site':'trend'; openOpsDrilldown(kind,title);};}); root.querySelectorAll('.actionBtn,.toolbarBtn').forEach((el,i)=>{el.onclick=(ev)=>{ev.stopPropagation(); openOpsDrilldown(i%2===0?'site':'alarm',el.textContent.trim());};});}
