function opsActionButtons(btns){return `<div class="opsActions">${btns.map(b=>`<button class="actionBtn ${b[2]||''}">${icon(b[1])}<span>${esc(b[0])}</span></button>`).join('')}</div>`}
function mapCard(mode,title,sub,extra=''){return `<div class="dashcard opsCard ${mode==='heat'?'coverageMapCard':'opsMapCard'}"><div class="dashCardHead"><div><div class="dashTitle">${esc(title)}</div><div class="dashSub">${esc(sub)}</div></div><div class="liveBadge">${state.lang==='en'?'LIVE OSM':'OSM مباشر'}</div></div><div class="osmMap" id="liveOsmMap" data-mode="${mode}"></div><div class="mapLegend">${mapLegend(mode)}</div>${extra}</div>`}
function mapLegend(mode){const en=state.lang==='en';if(mode==='rollout')return `<div class="mapLegendItem"><span class="mapLegendDot" style="background:var(--green)"></span>${en?'Operational':'تشغيلي'}</div><div class="mapLegendItem"><span class="mapLegendDot" style="background:var(--blue)"></span>${en?'Planned':'مخطط'}</div><div class="mapLegendItem"><span class="mapLegendDot" style="background:var(--amber)"></span>${en?'Attention':'يحتاج انتباه'}</div>`;return `<div class="mapLegendItem"><span class="mapLegendDot" style="background:var(--green)"></span>${en?'Strong':'قوي'}</div><div class="mapLegendItem"><span class="mapLegendDot" style="background:var(--blue)"></span>${en?'Moderate':'متوسط'}</div><div class="mapLegendItem"><span class="mapLegendDot" style="background:var(--accent)"></span>${en?'Weak / hotspot':'ضعيف / بؤرة'}</div>`}
function networkStatusOpsTab(){const en=state.lang==='en';return `${commonKpis([[en?'Service Availability':'توافر الخدمة','99.98%',en?'24h rolling':'آخر 24 ساعة','shield'],[en?'Radio Coverage':'تغطية الراديو','87.4%',en?'Target 92%':'المستهدف 92%','signal'],[en?'Tower Count':'عدد الأبراج','20',en?'18 active • 2 planned':'18 نشط • 2 مخطط','tower'],[en?'Phase 1 Sites':'مواقع المرحلة الأولى','12',en?'8 live • 4 planned':'8 نشط • 4 مخطط','map'],[en?'Voice Util.':'استخدام الصوت','42%',en?'VoNR / AGNET':'VoNR / AGNET','phone'],[en?'Data Util.':'استخدام البيانات','68%',en?'14.2 Gbit/s peak':'ذروة 14.2 جيجابت/ث','line-chart']], 'kpi6')}<div class="opsGridA"><div class="opsCol two"><div class="dashcard opsCard"><div class="dashTitle">${en?'24-Hour Network Health':'صحة الشبكة خلال 24 ساعة'}</div><div class="dashSub">${en?'Availability, active sessions and throughput index by hour':'التوافر والجلسات النشطة ومؤشر الإنتاجية حسب الساعة'}</div>${networkHealthChart()}${networkHealthStats()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'Phase 1 Delivery Progress':'تقدم تنفيذ المرحلة الأولى'}</div><div class="dashSub">${en?'Operational readiness by workstream and immediate actions':'الجاهزية التشغيلية حسب مسار العمل والإجراءات الفورية'}</div>${phaseOpsBars()}${opsActionButtons([[en?'Open rollout board':'فتح لوحة الطرح','briefcase','blue'],[en?'View incident queue':'عرض قائمة الحوادث','bell','critical'],[en?'Export daily report':'تصدير التقرير اليومي','forward','green']])}</div></div><div class="opsCol three"><div class="dashcard opsCard"><div class="dashTitle">${en?'Tower Health Mix':'مزيج حالة الأبراج'}</div>${towerHealthDonut()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'24h Service Availability Matrix':'مصفوفة توافر الخدمة 24 ساعة'}</div><div class="dashSub">${en?'Six representative sites • dummy telemetry':'ستة مواقع تمثيلية • بيانات تجريبية'}</div>${availabilityHeatMatrix()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'Shift Snapshot':'ملخص الوردية'}</div><div class="dashSub">${en?'Operator-facing quick view of alarms and service posture':'عرض سريع موجّه للمشغّل لحالة الإنذارات والخدمة'}</div>${shiftSnapshot()}</div></div></div>`}
function radioCoverageOpsTab(){const en=state.lang==='en';return `${commonKpis([[en?'Radio Coverage':'تغطية الراديو','87.4%',en?'+3.2% vs baseline':'‎+3.2% مقابل الأساس','signal'],[en?'Active Towers':'الأبراج النشطة','18',en?'2 planned':'2 مخطط','tower'],[en?'Avg. RSRP':'متوسط RSRP','-79 dBm',en?'Good':'جيد','wifi'],[en?'Median SINR':'وسيط SINR','21 dB',en?'Healthy':'جيد','signal'],[en?'Poor Coverage':'تغطية ضعيفة','6.8%',en?'3 focus zones':'3 مناطق تركيز','map']])}<div class="opsGridC"><div class="opsCol">${mapCard('heat',en?'Radio Coverage Heat Map':'خريطة حرارية لتغطية الراديو',en?'Live OpenStreetMap tiles with illustrative coverage intensity':'خرائط OpenStreetMap مباشرة مع كثافة تغطية تجريبية',`<div class="opsActions" style="margin-top:10px"><button class="actionBtn blue">${icon('map')}<span>${en?'Open coverage layer':'فتح طبقة التغطية'}</span></button><button class="actionBtn">${icon('tower')}<span>${en?'Inspect weak zones':'فحص المناطق الضعيفة'}</span></button></div>`)}</div><div class="opsCol three"><div class="dashcard opsCard"><div class="dashTitle">${en?'RSRP Distribution':'توزيع RSRP'}</div><div class="dashSub">${en?'Serving signal strength buckets':'فئات قوة الإشارة'}</div>${rsrpHistogram()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'Coverage Quality Mix':'مزيج جودة التغطية'}</div>${coverageBandsVisual()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'Sector Load by Tower':'حمل القطاعات حسب البرج'}</div>${sectorLoadChart()}</div></div></div>`}
function voiceDataOpsTab(){const en=state.lang==='en';return `${commonKpis([[en?'Voice Utilization':'استخدام الصوت','42%',en?'VoNR + AGNET':'VoNR + AGNET','phone'],[en?'Data Utilization':'استخدام البيانات','68%',en?'14.2 Gbit/s peak':'ذروة 14.2 جيجابت/ث','line-chart'],[en?'Active Sessions':'الجلسات النشطة','8,426',en?'+12% today':'‎+12% اليوم','users'],[en?'VoNR Calls':'مكالمات VoNR','4,823',en?'99.1% completion':'99.1% إكمال','phone'],[en?'Avg Latency':'متوسط الكمون','5.8 ms',en?'P95 8.4 ms':'P95 8.4 ms','tachometer']])}<div class="opsGridB"><div class="opsCol two"><div class="dashcard opsCard"><div class="dashTitle">${en?'Voice & Data Utilization':'استخدام الصوت والبيانات'}</div><div class="dashSub">${en?'Independent service gauges with active-session mix':'مقاييس مستقلة للخدمة مع مزيج الجلسات النشطة'}</div>${dualOpsDials()}${sessionMixBars()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'24-Hour Traffic Profile':'ملف الحركة خلال 24 ساعة'}</div><div class="dashSub">${en?'Hourly voice, data and total carried load':'الصوت والبيانات وإجمالي الحمل المحمول كل ساعة'}</div>${voiceDataOpsTrend()}${trafficProfileStats()}</div></div><div class="opsCol two"><div class="dashcard opsCard"><div class="dashTitle">${en?'VoNR Call Completion Funnel':'قمع إكمال مكالمات VoNR'}</div>${callFunnel()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'Latency vs Throughput by Site':'الكمون مقابل الإنتاجية حسب الموقع'}</div><div class="dashSub">${en?'Illustrative correlation with service groups':'ارتباط تجريبي مع مجموعات الخدمة'}</div>${latencyScatter()}${opsActionButtons([[en?'View QoS profile':'عرض ملف QoS','eye','blue'],[en?'Tune threshold':'ضبط العتبة','tachometer','green']])}</div></div></div>`}
function phaseRolloutOpsTab(){const en=state.lang==='en';return `${commonKpis([[en?'Phase 1 Sites':'مواقع المرحلة الأولى','12',en?'8 on-air • 4 planned':'8 على الهواء • 4 مخطط','map'],[en?'Site Ready':'المواقع الجاهزة','67%',en?'Civil + power + backhaul':'الأعمال المدنية + الطاقة + الربط','building'],[en?'RAN Integrated':'دمج RAN','78%',en?'10 / 12 sites':'10 / 12 مواقع','tower'],[en?'Acceptance':'القبول','58%',en?'ATP in progress':'ATP جارٍ','check'],[en?'Milestones On Time':'المعالم في الوقت','83%',en?'1 watch item':'عنصر واحد للمراقبة','bell']])}<div class="opsGridD"><div class="opsCol two"><div class="dashcard opsCard"><div class="dashTitle">${en?'Phase 1 Milestone Rail':'مسار معالم المرحلة الأولى'}</div><div class="dashSub">${en?'Progress from design approval to service acceptance':'التقدم من اعتماد التصميم حتى قبول الخدمة'}</div>${phaseMilestoneRail()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'Site Readiness Tracker':'متتبع جاهزية المواقع'}</div><div class="dashSub">${en?'Representative site-level readiness and next action':'جاهزية تمثيلية على مستوى المواقع والإجراء التالي'}</div>${siteReadinessTable()}</div></div><div class="opsCol two"><div class="dashcard opsCard"><div class="dashTitle">${en?'Weekly Rollout Throughput':'إنتاجية الطرح الأسبوعية'}</div><div class="dashSub">${en?'Live, planned and acceptance-complete sites by week':'المواقع النشطة والمخططة والمقبولة حسب الأسبوع'}</div>${rolloutWaveChart()}<div class="legendRow"><div class="legendItem"><span class="legendSw" style="background:var(--green)"></span>${en?'On-air':'على الهواء'}</div><div class="legendItem"><span class="legendSw" style="background:var(--blue)"></span>${en?'Planned':'مخطط'}</div><div class="legendItem"><span class="legendSw" style="background:var(--amber)"></span>${en?'Accepted':'مقبول'}</div></div></div><div class="dashcard opsCard"><div class="dashTitle">${en?'Rollout Control Actions':'إجراءات التحكم في الطرح'}</div><div class="dashSub">${en?'Dummy controls for a programme management cockpit':'عناصر تحكم تجريبية لواجهة إدارة البرنامج'}</div><div class="phaseSummary"><div class="miniStat"><strong>2</strong><span>${en?'Blocked permits':'تصاريح متعثرة'}</span></div><div class="miniStat"><strong>4</strong><span>${en?'ATP packs ready':'حزم ATP جاهزة'}</span></div><div class="miniStat"><strong>3</strong><span>${en?'Pending surveys':'مسوحات معلقة'}</span></div><div class="miniStat"><strong>1</strong><span>${en?'Escalations':'تصعيدات'}</span></div></div>${opsActionButtons([[en?'View site pack':'عرض حزمة الموقع','briefcase','blue'],[en?'Open permit tracker':'فتح متتبع التصاريح','map','green'],[en?'Escalate blocker':'تصعيد المعوق','bell','critical'],[en?'Download ATP list':'تنزيل قائمة ATP','forward','']])}</div></div></div>`}
function operationsOpsTab(){const en=state.lang==='en';return `${commonKpis([[en?'Open Incidents':'الحوادث المفتوحة','5',en?'2 high priority':'2 أولوية عالية','bell'],[en?'MTTR':'متوسط زمن الإصلاح','12 min',en?'Target < 15':'المستهدف < 15','refresh'],[en?'SLA Compliance':'الالتزام بـ SLA','99.4%',en?'Monthly':'شهري','check'],[en?'Dispatch Teams':'فرق الإرسال','4',en?'3 field • 1 standby':'3 ميداني • 1 احتياطي','users'],[en?'Change Windows':'نوافذ التغيير','2',en?'Tonight':'الليلة','refresh']])}<div class="opsGridC"><div class="opsCol">${mapCard('rollout',en?'Operational Site Map':'خريطة المواقع التشغيلية',en?'OpenStreetMap with operational and planned Phase 1 sites':'OpenStreetMap مع مواقع المرحلة الأولى التشغيلية والمخططة',`<div class="opsActions" style="margin-top:10px"><button class="actionBtn critical">${icon('bell')}<span>${en?'View incident':'عرض الحادث'}</span></button><button class="actionBtn blue">${icon('users')}<span>${en?'Dispatch team':'إرسال فريق'}</span></button><button class="actionBtn green">${icon('check')}<span>${en?'Close work order':'إغلاق أمر العمل'}</span></button></div>`)}</div><div class="opsCol three"><div class="dashcard opsCard"><div class="dashTitle">${en?'Incident Timeline':'الخط الزمني للحوادث'}</div>${incidentTimeline()}${responseSummary()}</div><div class="dashcard opsCard"><div class="dashTitle">${en?'SLA Compliance & Aging':'الالتزام بـ SLA وتقادم الإجراءات'}</div><div class="cardSplit"><div>${slaVisual()}</div><div>${actionAgingChart()}</div></div></div><div class="dashcard opsCard"><div class="dashTitle">${en?'Open Ticket Worklist':'قائمة التذاكر المفتوحة'}</div><div class="dashSub">${en?'Professional dummy work queue':'قائمة عمل تجريبية احترافية'}</div>${ticketWorklist()}</div></div></div>`}
function networkHealthChart(){const en=state.lang==='en';const times=['00','04','08','12','16','20','24'];return `<svg class="opsChart tall" viewBox="0 0 650 220"><defs><linearGradient id="nhA2" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(90,132,255,.28)"/><stop offset="100%" stop-color="rgba(90,132,255,0)"/></linearGradient><linearGradient id="nhR2" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(255,49,77,.16)"/><stop offset="100%" stop-color="rgba(255,49,77,0)"/></linearGradient></defs><g opacity=".14">${[35,70,105,140,175].map(y=>`<line x1="48" y1="${y}" x2="622" y2="${y}" stroke="var(--muted)"/>`).join('')}</g><path class="areaReveal" d="M48 148 C96 142 138 126 182 118 S266 108 312 96 S402 88 452 80 S542 72 622 66 L622 190 L48 190Z" fill="url(#nhA2)"/><path class="areaReveal" d="M48 162 C96 158 138 154 182 145 S266 136 312 130 S402 122 452 119 S542 112 622 106 L622 190 L48 190Z" fill="url(#nhR2)"/><path class="drawPath" d="M48 148 C96 142 138 126 182 118 S266 108 312 96 S402 88 452 80 S542 72 622 66" fill="none" stroke="var(--blue)" stroke-width="4" stroke-linecap="round"/><path class="drawPath delay" d="M48 162 C96 158 138 154 182 145 S266 136 312 130 S402 122 452 119 S542 112 622 106" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linecap="round"/><path class="drawPath" style="animation-delay:.25s" d="M48 58 C96 60 138 58 182 56 S266 59 312 57 S402 58 452 54 S542 56 622 53" fill="none" stroke="var(--green)" stroke-width="3" stroke-linecap="round"/>${[48,144,240,336,432,528,622].map((x,i)=>`<g><circle cx="${x}" cy="${[148,138,118,96,80,72,66][i]}" r="4" fill="var(--blue)"/><circle cx="${x}" cy="${[162,156,145,130,119,112,106][i]}" r="3.6" fill="var(--accent)"/><circle cx="${x}" cy="${[58,59,56,57,55,56,53][i]}" r="3.4" fill="var(--green)"/></g>`).join('')}<g fill="var(--muted)" font-size="10">${times.map((x,i)=>`<text x="${48+i*95.6}" y="208">${x}</text>`).join('')}</g><g font-size="9" font-weight="800"><text x="468" y="26" fill="var(--green)">${en?'Availability %':'التوافر %'}</text><text x="546" y="26" fill="var(--blue)">${en?'Traffic idx':'مؤشر الحركة'}</text><text x="607" y="26" text-anchor="end" fill="var(--accent)">${en?'Sessions':'الجلسات'}</text></g></svg>`}
function networkHealthStats(){const en=state.lang==='en';return `<div class="miniStats"><div class="miniStat"><strong>99.98%</strong><span>${en?'Best hour availability':'أفضل ساعة توافر'}</span></div><div class="miniStat"><strong>8.4k</strong><span>${en?'Peak active sessions':'ذروة الجلسات النشطة'}</span></div><div class="miniStat"><strong>14.2G</strong><span>${en?'Peak throughput':'ذروة الإنتاجية'}</span></div></div>`}
function phaseOpsBars(){const en=state.lang==='en';const rows=[[en?'Site readiness':'جاهزية المواقع',67],[en?'RAN integration':'دمج RAN',78],[en?'Core onboarding':'إدخال النواة',84],[en?'Acceptance':'القبول',58]];return `<div class="phaseBars">${rows.map(r=>`<div class="phaseBarRow"><div>${esc(r[0])}</div><div class="phaseTrack"><div class="phaseFill" style="width:${r[1]}%"></div></div><strong>${r[1]}%</strong></div>`).join('')}</div>`}
function towerHealthDonut(){const en=state.lang==='en';return `<div class="towerMixWrap"><div class="towerMixDonut"><div class="towerMixRing"><div class="towerMixInner"><strong>20</strong><span>${en?'Towers':'الأبراج'}</span><small>${en?'17 healthy • 2 planned • 1 attention':'17 سليم • 2 مخطط • 1 يحتاج متابعة'}</small></div></div></div><div class="towerMixLegend"><div class="towerLegendRow good"><div class="towerLegendHead"><span class="sw"></span><strong>${en?'Healthy':'سليم'}</strong></div><b>17</b><div class="phaseTrack"><div class="phaseFill" style="width:85%;background:var(--green)"></div></div><small>85%</small></div><div class="towerLegendRow plan"><div class="towerLegendHead"><span class="sw"></span><strong>${en?'Planned':'مخطط'}</strong></div><b>2</b><div class="phaseTrack"><div class="phaseFill" style="width:10%;background:var(--blue)"></div></div><small>10%</small></div><div class="towerLegendRow warn"><div class="towerLegendHead"><span class="sw"></span><strong>${en?'Attention':'انتباه'}</strong></div><b>1</b><div class="phaseTrack"><div class="phaseFill" style="width:5%;background:var(--amber)"></div></div><small>5%</small></div><div class="towerMixFooter"><div class="miniStat"><strong>${en?'99.4%':'99.4%'}</strong><span>${en?'Availability':'التوافر'}</span></div><div class="miniStat"><strong>${en?'2.1h':'2.1h'}</strong><span>${en?'Avg maintenance':'متوسط الصيانة'}</span></div></div></div></div>`}
function availabilityHeatMatrix(){const labels=['Apollo','Khaznah','P1-S05','P1-S07','MOD HQ','Mubadala'];let cells='';labels.forEach((l,r)=>{cells+=`<div class="heatLabel">${l}</div>`;for(let c=0;c<12;c++){const bad=(r===2&&c===7)||(r===4&&c===9);const warn=(r===1&&c===4)||(r===5&&c===6);cells+=`<div class="heatCell ${bad?'hot':warn?'warn':''}" title="${bad?'Service event':warn?'Minor degradation':'Healthy'}"></div>`}});return `<div class="heatMatrix"><div></div>${Array.from({length:12},(_,i)=>`<div class="heatLabel" style="text-align:center">${i*2}</div>`).join('')}${cells}</div>`}
function shiftSnapshot(){const en=state.lang==='en';return `<div class="sparkRow"><div class="sparkCard"><strong>05</strong><span>${en?'Open alarms':'إنذارات مفتوحة'}</span>${sparkline([11,10,8,9,7,5],'var(--accent)')}</div><div class="sparkCard"><strong>18</strong><span>${en?'Sites monitored':'مواقع مُراقبة'}</span>${sparkline([8,9,9,10,11,12],'var(--blue)')}</div><div class="sparkCard"><strong>03</strong><span>${en?'Degraded services':'خدمات متدهورة'}</span>${sparkline([6,6,5,4,4,3],'var(--amber)')}</div><div class="sparkCard"><strong>99.4%</strong><span>${en?'Current SLA':'SLA الحالي'}</span>${sparkline([95,96,97,98,99,99.4],'var(--green)')}</div></div>`}
function sparkline(vals,color){const max=Math.max(...vals),min=Math.min(...vals),rng=max-min||1;const pts=vals.map((v,i)=>`${i*(100/(vals.length-1))},${30-((v-min)/rng)*22}`).join(' ');return `<svg class="sparkSvg" viewBox="0 0 100 36"><polyline fill="none" stroke="${color}" stroke-width="2.6" points="${pts}" stroke-linecap="round" stroke-linejoin="round"/><circle cx="100" cy="${30-((vals[vals.length-1]-min)/rng)*22}" r="2.8" fill="${color}"/></svg>`}
function rsrpHistogram(){const vals=[18,30,48,72,92,76,50,28,14];return `<div class="rsrpHist">${vals.map((v,i)=>`<div class="histBar ${i<2?'bad':i>5?'good':''}" style="--h:${v}%" title="${-112+i*5} dBm"></div>`).join('')}</div><div style="display:flex;justify-content:space-between;font-size:8px;color:var(--muted)"><span>-112 dBm</span><span>-90</span><span>-72 dBm</span></div>`}
function coverageBandsVisual(){const en=state.lang==='en';return `<div class="coverageBand"><div class="bandCard"><div class="bandVal" style="color:var(--green)">42%</div><div class="bandLbl">${en?'Excellent':'ممتاز'}</div></div><div class="bandCard"><div class="bandVal" style="color:var(--blue)">37%</div><div class="bandLbl">${en?'Good':'جيد'}</div></div><div class="bandCard"><div class="bandVal" style="color:var(--amber)">14%</div><div class="bandLbl">${en?'Fair':'متوسط'}</div></div><div class="bandCard"><div class="bandVal" style="color:var(--accent)">7%</div><div class="bandLbl">${en?'Poor':'ضعيف'}</div></div></div>`}
function sectorLoadChart(){const vals=[64,72,58,81,69,54];return `<svg class="opsChart compact" viewBox="0 0 430 145"><g opacity=".14">${[30,60,90].map(y=>`<line x1="32" y1="${y}" x2="405" y2="${y}" stroke="var(--muted)"/>`).join('')}</g>${vals.map((v,i)=>`<rect class="barGrow" x="${45+i*60}" y="${116-v}" width="34" height="${v}" rx="7" fill="${v>78?'var(--accent)':i%2?'var(--blue)':'var(--green)'}"/><text x="${62+i*60}" y="137" text-anchor="middle" font-size="8" fill="var(--muted)">T${i+1}</text><text x="${62+i*60}" y="${110-v}" text-anchor="middle" font-size="8" fill="var(--text)">${v}%</text>`).join('')}</svg>`}
function dualOpsDials(){return `<div class="utilDialRow">${utilDial(42,state.lang==='en'?'Voice':'الصوت','voiceArc')}${utilDial(68,state.lang==='en'?'Data':'البيانات','dataArc')}</div>`}
function utilDial(p,label,cls){const dash=251.3,off=dash*(1-p/100);return `<div class="utilDial"><svg viewBox="0 0 100 100"><circle class="track" cx="50" cy="50" r="40"/><circle class="arc ${cls}" cx="50" cy="50" r="40" stroke-dasharray="${dash}" stroke-dashoffset="${off}"/></svg><div class="utilDialText"><strong>${p}%</strong><span>${esc(label)}</span></div></div>`}
function sessionMixBars(){const en=state.lang==='en';const rows=[[en?'AGNET':'AGNET',24],[en?'VoNR':'VoNR',46],[en?'Video':'فيديو',68],[en?'IoT / CCTV':'إنترنت الأشياء / CCTV',82]];return `<div class="trafficMix">${rows.map(r=>`<div class="mixRow"><div>${esc(r[0])}</div><div class="mixBar"><div class="mixFill" style="width:${r[1]}%"></div></div><div>${r[1]}%</div></div>`).join('')}</div>`}
function voiceDataOpsTrend(){const en=state.lang==='en';const xs=[56,128,200,272,344,416,488,560],voice=[144,138,132,126,118,108,98,92],data=[120,112,98,92,84,72,64,58],total=[102,96,88,78,70,62,54,48];const labels=['00','03','06','09','12','15','18','21'];const grid=[40,72,104,136,168];const poly=a=>a.map((y,i)=>`${xs[i]},${y}`).join(' ');return `<div class="trafficLegend"><div class="legendItem"><span class="legendSw" style="background:var(--blue)"></span>${en?'Data':'البيانات'}</div><div class="legendItem"><span class="legendSw" style="background:var(--accent)"></span>${en?'Voice':'الصوت'}</div><div class="legendItem"><span class="legendSw dashed"></span>${en?'Total carried load':'إجمالي الحمل المحمول'}</div></div><svg class="opsChart tall opsTrafficChart" viewBox="0 0 620 210"><defs><linearGradient id="trafficBlueFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(90,132,255,.32)"/><stop offset="100%" stop-color="rgba(90,132,255,0)"/></linearGradient><linearGradient id="trafficRedFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(255,49,77,.28)"/><stop offset="100%" stop-color="rgba(255,49,77,0)"/></linearGradient></defs><g opacity=".14">${grid.map(y=>`<line x1="50" y1="${y}" x2="580" y2="${y}" stroke="var(--muted)"/>`).join('')}</g><g opacity=".08">${xs.map(x=>`<line x1="${x}" y1="32" x2="${x}" y2="172" stroke="var(--muted)"/>`).join('')}</g><path class="areaReveal" d="M${xs[0]} ${data[0]} ${xs.slice(1).map((x,i)=>`L${x} ${data[i+1]}`).join(' ')} L560 172 L56 172 Z" fill="url(#trafficBlueFill)"/><path class="areaReveal" d="M${xs[0]} ${voice[0]} ${xs.slice(1).map((x,i)=>`L${x} ${voice[i+1]}`).join(' ')} L560 172 L56 172 Z" fill="url(#trafficRedFill)"/><polyline class="drawPath" points="${poly(data)}" fill="none" stroke="var(--blue)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><polyline class="drawPath delay" points="${poly(voice)}" fill="none" stroke="var(--accent)" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/><polyline class="drawPath" style="animation-delay:.24s" points="${poly(total)}" fill="none" stroke="var(--green)" stroke-width="2.6" stroke-dasharray="5 6" stroke-linecap="round" stroke-linejoin="round"/>${xs.map((x,i)=>`<g><circle cx="${x}" cy="${data[i]}" r="4.2" fill="var(--blue)"/><circle cx="${x}" cy="${voice[i]}" r="3.6" fill="var(--accent)"/><circle cx="${x}" cy="${total[i]}" r="2.8" fill="var(--green)"/></g>`).join('')}<g fill="var(--muted)" font-size="8.5" font-weight="800">${labels.map((lbl,i)=>`<text x="${xs[i]}" y="190" text-anchor="middle">${lbl}</text>`).join('')}</g><g fill="var(--muted)" font-size="8.5">${['Low','Med','Busy','Peak'].map((lbl,i)=>`<text x="18" y="${154-i*34}">${en?lbl:['منخفض','متوسط','نشط','ذروة'][i]}</text>`).join('')}</g></svg>`}
