function phaseMilestoneRail(){const en=state.lang==='en';const rows=[[en?'Design approval':'اعتماد التصميم',en?'Completed':'مكتمل','done','check'],[en?'Civil & power':'الأعمال المدنية والطاقة',en?'10/12 sites progressing':'10/12 موقع قيد التنفيذ','done','building'],[en?'Backhaul readiness':'جاهزية الربط',en?'8 sites live':'8 مواقع نشطة','live','link'],[en?'ATP & acceptance':'ATP والقبول',en?'4 sites pending ATP':'4 مواقع بانتظار ATP','next','check'],[en?'Service go-live':'الإطلاق الخدمي',en?'Wave 2 planning':'تخطيط الموجة 2','plan','rocket']];return `<div class="phaseRailWrap"><div class="phaseRailHead"><div class="phaseRailProgress"><div class="phaseRailFill"></div></div><div class="phaseRailPct"><strong>78%</strong><span>${en?'overall completion':'إجمالي الإنجاز'}</span></div></div><div class="phaseRailNodes">${rows.map((r,i)=>`<div class="phaseStep ${r[2]}"><div class="phaseStepDot">${icon(r[3])}</div><div class="phaseStepBody"><strong>${r[0]}</strong><span>${r[1]}</span></div></div>${i<rows.length-1?'<div class="phaseConnector"></div>':''}`).join('')}</div><div class="phaseRailSummary"><div class="miniStat"><strong>3</strong><span>${en?'Workstreams closed':'مسارات أغلقت'}</span></div><div class="miniStat"><strong>2</strong><span>${en?'Gate reviews left':'مراجعات متبقية'}</span></div><div class="miniStat"><strong>29 Aug</strong><span>${en?'Next milestone date':'موعد المعلم التالي'}</span></div></div></div>`}
