function incidentTimeline(){const en=state.lang==='en';const rows=[['08:12','bad',en?'Backhaul jitter exceeded':'تجاوز ارتجاج الربط','Apollo DC'],['09:05','warn',en?'Sector load high':'حمل قطاع مرتفع','P1-S07'],['10:28','',en?'Alarm cleared':'تمت إزالة التنبيه','Khaznah'],['11:42','',en?'Site check completed':'اكتمل فحص الموقع','MOD HQ']];return `<div class="opsTimeline">${rows.map(r=>`<div class="timelineRow"><div class="timelineTime">${r[0]}</div><div class="timelineDot ${r[1]}"></div><div class="timelineText">${r[2]}<span>${r[3]}</span></div></div>`).join('')}</div>`}
