function ticketWorklist(){const en=state.lang==='en';const rows=[[en?'INC-24081':'INC-24081',en?'Apollo backhaul jitter':'ارتجاج ربط Apollo',en?'Field team':'فريق ميداني','bad'],[en?'WO-24033':'WO-24033',en?'P1-S07 sector balancing':'موازنة قطاع P1-S07',en?'RAN desk':'مكتب RAN','warn'],[en?'CHG-24012':'CHG-24012',en?'VoNR policy update':'تحديث سياسة VoNR',en?'Core team':'فريق النواة','blue']];return `<div class="opsTable"><div class="opsTableHead"><div>${en?'ID':'المعرف'}</div><div>${en?'Subject':'الموضوع'}</div><div>${en?'Owner':'المالك'}</div><div>${en?'State':'الحالة'}</div></div>${rows.map(r=>`<div class="opsTableRow"><div>${r[0]}</div><div>${r[1]}</div><div>${r[2]}</div><div><span class="statusPill ${r[3]}">${r[3]==='bad'?(en?'Open':'مفتوح'):r[3]==='warn'?(en?'In progress':'قيد التنفيذ'):(en?'Planned':'مخطط')}</span></div></div>`).join('')}</div>${opsActionButtons([[en?'View incident':'عرض الحادث','eye','critical'],[en?'Open work order':'فتح أمر العمل','briefcase','blue'],[en?'Send update':'إرسال تحديث','forward','green']])}`}
function osmProject(lat,lon,z){const n=Math.pow(2,z)*256;const x=(lon+180)/360*n;const r=lat*Math.PI/180;const y=(1-Math.log(Math.tan(r)+1/Math.cos(r))/Math.PI)/2*n;return{x,y}}
function osmUnproject(x,y,z){const n=Math.pow(2,z)*256;const lon=x/n*360-180;const a=Math.PI-2*Math.PI*y/n;const lat=180/Math.PI*Math.atan(.5*(Math.exp(a)-Math.exp(-a)));return{lat,lon}}
function initDashboardMap(){const el=document.getElementById('liveOsmMap');if(!el)return;const mode=el.dataset.mode||'sites';let center={lat:24.43,lon:54.57};let zoom=10;let dragging=false,start=null,startCenter=null;const allowTiles=!USE_OFFLINE_MAP;const fallback=state.theme==='dark'?ASSETS.mapDark:ASSETS.mapLight;el.style.backgroundImage=cssAsset(fallback);el.innerHTML='<div class="osmTileLayer"></div><div class="osmMapShade"></div><div class="osmOverlayLayer"></div><div class="mapFallbackNote">'+(allowTiles?(state.lang==='en'?'Live OpenStreetMap':'خريطة OpenStreetMap حية'):(state.lang==='en'?'Embedded fallback map':'خريطة احتياطية مدمجة'))+'</div>'+(allowTiles?'<div class="osmAttribution">© OpenStreetMap contributors</div>':'')+'<div class="osmControls"><button class="osmCtrl" data-z="1">+</button><button class="osmCtrl" data-z="-1">−</button></div>';const tileLayer=el.querySelector('.osmTileLayer'),overlay=el.querySelector('.osmOverlayLayer');
function draw(){tileLayer.innerHTML='';overlay.innerHTML='';const w=el.clientWidth,h=el.clientHeight;const cp=osmProject(center.lat,center.lon,zoom);const minX=cp.x-w/2-256,maxX=cp.x+w/2+256,minY=cp.y-h/2-256,maxY=cp.y+h/2+256;const tminX=Math.floor(minX/256),tmaxX=Math.floor(maxX/256),tminY=Math.floor(minY/256),tmaxY=Math.floor(maxY/256);if(allowTiles){for(let tx=tminX;tx<=tmaxX;tx++)for(let ty=tminY;ty<=tmaxY;ty++){const img=document.createElement('img');img.className='osmTile';img.draggable=false;img.src=`https://tile.openstreetmap.org/${zoom}/${tx}/${ty}.png`;img.style.left=(tx*256-cp.x+w/2)+'px';img.style.top=(ty*256-cp.y+h/2)+'px';img.onerror=()=>img.remove();tileLayer.appendChild(img);}}const mpp=156543.03392*Math.cos(center.lat*Math.PI/180)/Math.pow(2,zoom);DASH_SITES.forEach((s,i)=>{const p=osmProject(s.lat,s.lon,zoom);const px=p.x-cp.x+w/2,py=p.y-cp.y+h/2;if(px<-120||px>w+120||py<-120||py>h+120)return;if(mode==='sites'||mode==='heat'||mode==='traffic'){const radius=(mode==='heat'?5500:mode==='traffic'?3500:4200)/mpp;const ring=document.createElement('div');ring.className=mode==='heat'||mode==='traffic'?'heatSpot':'coverageRing';ring.style.left=px+'px';ring.style.top=py+'px';ring.style.width=ring.style.height=(radius*2)+'px';if(mode==='traffic')ring.style.opacity=Math.max(.35,Math.min(1,s.load/90));overlay.appendChild(ring);}const mk=document.createElement('div');mk.className='siteMarker '+(mode==='security'&&i%3===0?'security':s.status);mk.style.left=px+'px';mk.style.top=py+'px';mk.innerHTML='<div class="siteDot"></div><div class="siteLabel">'+s.name+'</div>';overlay.appendChild(mk);if(mode==='security'&&i%3===0){const heat=document.createElement('div');heat.className='heatSpot';heat.style.left=px+'px';heat.style.top=py+'px';heat.style.width=heat.style.height=(80+(i%4)*24)+'px';overlay.appendChild(heat);}})}
function redraw(){requestAnimationFrame(draw)}el.querySelectorAll('.osmCtrl').forEach(b=>b.onclick=e=>{e.stopPropagation();zoom=Math.max(8,Math.min(15,zoom+Number(b.dataset.z)));redraw()});el.addEventListener('pointerdown',e=>{dragging=true;el.classList.add('dragging');el.setPointerCapture(e.pointerId);start={x:e.clientX,y:e.clientY};startCenter=osmProject(center.lat,center.lon,zoom)});el.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;const c=osmUnproject(startCenter.x-dx,startCenter.y-dy,zoom);center=c;draw()});el.addEventListener('pointerup',()=>{dragging=false;el.classList.remove('dragging')});el.addEventListener('pointercancel',()=>{dragging=false;el.classList.remove('dragging')});draw();}
function initDashboardAnimations(){if(state.slide!==8)return;initDashboardMap();document.querySelectorAll('.dashKpiValue').forEach((el,i)=>{el.animate([{opacity:.25,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:450+i*55,easing:'cubic-bezier(.2,.7,.2,1)',fill:'both'})})}
