function bindDashboardTabs(){document.querySelectorAll('.dashTabBtn').forEach(b=>b.onclick=()=>{const next=+b.dataset.tab;if(next===state.dashTab)return;state.dashTab=next;document.querySelectorAll('.dashTabBtn').forEach((x,i)=>x.classList.toggle('active',i===state.dashTab));const root=document.getElementById('opsPortal')?.classList.contains('open')?document.getElementById('opsPortal'):document.querySelector('.slide.active');const sh=root?.querySelector('.dashboardShell');const pane=root?.querySelector('.dashPane');if(sh)sh.dataset.tab=state.dashTab;if(pane){pane.className='dashPane dashPane'+state.dashTab;pane.innerHTML=dashboardContent();requestAnimationFrame(()=>{initDashboardAnimations();bindOpsDrilldowns();});}});}
function bindDynamic(){bindDashboardTabs();bindArchitecture();document.querySelectorAll('.js-open-ops-overlay').forEach(b=>b.onclick=()=>openOpsOverlay());}
function onSlideEnter(idx){
 clearInterval(window.__tw);
 if(idx===0){typewriterScript();startIntroAnimations();}
 if(idx===1)startBriefAnimations();
 if(idx===3)setTimeout(bindArchitecture,40);
 if(idx===7)setTimeout(initPocMap,50);

}
function setActiveSlide(next,dir,instant=false){document.documentElement.setAttribute('data-navdir',String(dir));document.querySelectorAll('#slides>.slide').forEach((s,i)=>s.classList.toggle('active',i===next));state.slide=next;setDeckProgress();applyNavDepth();centerActiveNav(instant);syncNavSlider();onSlideEnter(next);requestAnimationFrame(fit);}
let __slideSwitchLock=false;function go(i){const next=(i+TOTAL_SLIDES)%TOTAL_SLIDES;if(next===state.slide||__slideSwitchLock)return;closeOpsOverlay();__slideSwitchLock=true;const dir=next>state.slide?1:-1;navRail.dataset.dir=String(dir);navRail.classList.remove('navmoving');void navRail.offsetWidth;navRail.classList.add('navmoving');document.body.classList.remove('slide-switching');void document.body.offsetWidth;document.body.classList.add('slide-switching');setActiveSlide(next,dir,false);setTimeout(()=>{navRail.classList.remove('navmoving');document.body.classList.remove('slide-switching');__slideSwitchLock=false;},430);}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark'; render();}
function toggleLang(){state.lang=state.lang==='en'?'ar':'en'; render();}
function toggleFullscreen(){if(!document.fullscreenElement) document.documentElement.requestFullscreen?.(); else document.exitFullscreen?.();}
navRail.addEventListener('wheel',e=>{if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){navRail.scrollLeft+=e.deltaY*.7;e.preventDefault();}},{passive:false});
document.getElementById('themeBtn').onclick=toggleTheme; document.getElementById('langBtn').onclick=toggleLang; document.getElementById('fullBtn').onclick=toggleFullscreen;
const __edgePrev=document.getElementById('edgePrev'); const __edgeNext=document.getElementById('edgeNext'); if(__edgePrev)__edgePrev.onclick=()=>go(state.slide-1); if(__edgeNext)__edgeNext.onclick=()=>go(state.slide+1);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('#opsPortal.open .opsDrilldown.open')){closeOpsDrilldown();return;} if(document.querySelector('#opsPortal.open')){closeOpsOverlay();return;}} if(e.key==='ArrowRight'||e.key==='PageDown'||e.key===' ') go(state.slide+1); if(e.key==='ArrowLeft'||e.key==='PageUp') go(state.slide-1); if(e.key.toLowerCase()==='d') toggleTheme(); if(e.key.toLowerCase()==='l') toggleLang(); if(e.key.toLowerCase()==='f') toggleFullscreen();});
window.addEventListener('resize',()=>{fit(); centerActiveNav(true); syncNavSlider();}); if(window.visualViewport){window.visualViewport.addEventListener('resize',()=>{fit(); centerActiveNav(true); syncNavSlider();});} document.addEventListener('fullscreenchange',()=>requestAnimationFrame(()=>{fit(); centerActiveNav(true); syncNavSlider();})); window.go=go; window.toggleFullscreen=toggleFullscreen; window.openOpsOverlay=openOpsOverlay; window.closeOpsOverlay=closeOpsOverlay; const __baseRender=render; render=function(){__baseRender(); setTimeout(()=>{onSlideEnter(state.slide);centerActiveNav(true); syncNavSlider();},60)}; render(); requestAnimationFrame(()=>{fit(); centerActiveNav(true); syncNavSlider();}); setTimeout(()=>{fit(); centerActiveNav(true); syncNavSlider();},120);
